{
  "ContainsFormulation": true,
  "variablesInModel": [
    {
      "Number": 1,
      "Abbreviation": "p_{tq}",
      "Name": "platform assignment",
      "Description": "1 if train t uses platform q",
      "Domain": "binary"
    },
    {
      "Number": 2,
      "Abbreviation": "s_t",
      "Name": "start time",
      "Description": "start time of train t at the platform",
      "Domain": "continuous"
    }
