  "objective_functions": [
    {
      "Name": "minimize the cost of the platform assignment",
      "Number": 0,
      "equation": "\\min \\sum_{t \\in T} \\sum_{q \\in Q} \\kappa_{tq} p_{tq}",
      "description": "We minimize the cost of the platform assignment.",
      "VariablesIncluded": [
        1
      ],
      "Linear": true
    }
  ],
  "constraints": [
    {
      "Name": "One platform",
      "Number": 1,
      "equation": "\\sum_{q \\in Q} p_{tq} = 1 \\quad \\forall t \\in T",
      "description": "Each train must be assigned to exactly one platform.",
      "VariablesIncluded": [
        1
      ],
      "Linear": true
    },
    {
      "Name": "Planned start",
      "Number": 2,
      "equation": "s_t \\ge \\sigma_t \\quad \\forall t \\in T",
      "description": "The start time must be greater than or equal to the planned start.",
      "VariablesIncluded": [
        2
      ],
      "Linear": true
    }
  ]
}
